import Phaser from 'phaser';

/**
 * Enemy and boss sprite sheet (public/assets/sprites.png, generated by
 * `npm run sprites` from art/sprites.mjs). Each frame becomes its own texture
 * under its frame name (walker0, anvil_idle, ...), which is what the game code
 * refers to.
 */
export function preloadSprites(scene: Phaser.Scene): void {
  scene.load.image('sprites_sheet', 'assets/sprites.png');
  scene.load.json('sprites_index', 'assets/sprites.json');
}

export function createSpriteTextures(scene: Phaser.Scene): void {
  const index = scene.cache.json.get('sprites_index') as Record<string, [number, number, number, number]>;
  const src = scene.textures.get('sprites_sheet').getSourceImage() as HTMLImageElement;
  for (const [key, [x, y, w, h]] of Object.entries(index)) {
    const tex = scene.textures.createCanvas(key, w, h)!;
    tex.getContext().drawImage(src, x, y, w, h, 0, 0, w, h);
    tex.refresh();
  }
}
